ECS = {}

-- call this to (re)initialize per-player settings
InitializeECS = function()
	ECS.Mode = "Warmup"
	ECS.IsPractice = false
	ECS.BreakTimer=(15 * 60)
	ECS.SetTimer=(60 * 60)
	ECS.SpeedAttemptNumber = 0
	ECS.TimeToRemoveFromBreakTimer = 0

	ECS.Player = {
		Profile=nil,
		Relics={},
		-- Use AddPlayedSongs to append to this table which will keep this table
		-- sorted in descending order of points.
		SongsPlayed={},
		-- Also updated in AddPlayedSongs below.
		ConsecutivePasses = 0,
		StethoscopeActive = false,
		MixTapesRandomSong = nil,
		WrapperActive = false,
		EternalYouthActive = false,

		TotalMarathonPoints=0,
		MarathonRateMod=1,
	}
end

local UsingMedalOfFreedom = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Medal of Freedom") then
			return true
		end
	end
	return false
end

local BowEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Short Bow" or name == "Composite Bow" or name == "Long Bow" or name == "Twisted Bow" or
			name == "Taulmaril" or name == "Taulmaril +1" or name == "Taulmaril +2" or
			name == "Gontr Mael" or name == "Gontr Mael +1" or name == "Gontr Mael +2") then
			return true
		end
	end
	return false
end

local ArrowEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Stone Arrow" or name == "Bronze Arrow" or name == "Mythril Arrow" or name == "Dragon Arrow") then
			return true
		end
	end
	return false
end

local GunEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Zapper" or name == "Zapper +1" or name == "Zapper +2" or
			name == "Evoker" or name == "Evoker +1" or name == "Evoker +2") then
			return true
		end
	end
	return false
end

local BulletEquipped = function(relics_used)
	for relic in ivalues(relics_used) do
		local name = relic.name
		if (name == "Bullet" or name == "Pulse Ammo") then
			return true
		end
	end
	return false
end

